			public VehicleGhostReplay()
			{
			}

			public VehicleGhostReplay(Vector3 P, Vector3 R, float TN, float Crpm, float CS, bool Nitro)
			{
				Position = P;
				Rotation = R;
				TurningAngle = TN;
				CurrentRPM = Crpm;
				CurrentSpeed = CS;
				UsingNitroThisFrame = Nitro;
			}

