		public unsafe static long GetWheelsPtr(Vehicle handle)
		{
			if (Memory.wheelsPtrOffset == 0)
			{
				Notification.Show("wheelsPtrOffset Returned 0");
				return 0L;
			}
			IntPtr memoryAddress = handle.MemoryAddress;
			return *(long*)(void*)(memoryAddress + Memory.wheelsPtrOffset);
		}

		private unsafe List<float> GetWheelRotationSpeeds(Vehicle handle)
		{
			long wheelsPtr = GetWheelsPtr(handle);
			int numWheels = Memory.GetNumWheels(handle);
			List<float> list = new List<float>();
			for (int i = 0; i < numWheels; i++)
			{
				list.Add(0f);
			}
			if (Memory.wheelAngularVelocityOffset == 0)
			{
				return list;
			}
			for (int j = 0; j < numWheels; j++)
			{
				int num = *(int*)(wheelsPtr + 8 * j);
				list[j] = 0f - *(float*)(num + Memory.wheelAngularVelocityOffset);
			}
			return list;
		}

		private unsafe float[] GetWheelRotations(Vehicle handle)
		{
			long wheelsPtr = GetWheelsPtr(handle);
			int numWheels = Memory.GetNumWheels(handle);
			float[] array = new float[numWheels];
			if (Memory.wheelAngleOffset == 0)
			{
				return array;
			}
			for (int i = 0; i < numWheels; i++)
			{
				long num = *(long*)(wheelsPtr + 8 * i);
				array[i] = *(float*)(num + Memory.wheelAngleOffset);
			}
			return array;
		}

		public unsafe static void SetWheelRotationSpeed(Vehicle handle, byte index, float value)
		{
			if (index <= Memory.GetNumWheels(handle) && Memory.wheelAngleOffset != 0)
			{
				long wheelsPtr = GetWheelsPtr(handle);
				long num = *(long*)(wheelsPtr + 8 * index);
				*(float*)(num + Memory.wheelAngleOffset) = value;
			}
		}

		public static Vector3 ToVector3(string Name)
		{
			Vector3 result = new Vector3(0f, 0f, 0f);
			string[] separator = new string[3] { "X:", "Y:", "Z:" };
			string[] array = Name.Split(separator, StringSplitOptions.RemoveEmptyEntries);
			try
			{
				result = new Vector3(float.Parse(array[0], CultureInfo.InvariantCulture), float.Parse(array[1], CultureInfo.InvariantCulture), float.Parse(array[2], CultureInfo.InvariantCulture));
				return result;
			}
			catch (Exception)
			{
				return result;
			}
		}

		public VehicleRecording()
		{
			base.Tick += Ontick;
		}

		private void drawText(string text, float x, float y, float scale, int r, int g, int b)
		{
			Function.Call(Hash.BEGIN_TEXT_COMMAND_DISPLAY_TEXT, "STRING");
			Function.Call(Hash.ADD_TEXT_COMPONENT_SUBSTRING_PLAYER_NAME, text);
			Function.Call(Hash.SET_TEXT_COLOUR, r, g, b, 255);
			Function.Call(Hash.SET_TEXT_SCALE, 0f, scale);
			Function.Call(Hash.END_TEXT_COMMAND_DISPLAY_TEXT, x, y, 0.1);
		}

		public static bool GetDistance_VDIST2(Vector3 _1, Vector3 _2, string Sign, float Radius)
		{
			bool result = false;
			float num = Radius * Radius;
			float num2 = Function.Call<float>(Hash.VDIST2, _1.X, _1.Y, _1.Z, _2.X, _2.Y, _2.Z);
			if (Sign.Equals("<=") && num2 <= num)
			{
				result = true;
			}
			if (Sign.Equals("<") && num2 < num)
			{
				result = true;
			}
			if (Sign.Equals(">=") && num2 >= num)
			{
				result = true;
			}
			if (Sign.Equals(">") && num2 > num)
			{
				result = true;
			}
			return result;
		}

		public void Ontick(object sender, EventArgs e)
		{
			if (!PlayingRecordedRoute && !Playing_TargetVehA_Route && !Playing_TargetVehB_Route && !Playing_TargetVehC_Route && !Playing_TargetVehC_Route)
			{
				return;
			}
			if (Playing_TargetVehA_Route && TheBillionaresParty.TargetVehicleA != null && TheBillionaresParty.TargetVehicleADriver != null)
			{
				if (Route_TargetVehA_Stage < BillionairVehicleAReplay.Count - 1)
				{
					TheBillionaresParty.TargetVehicleA.IsPositionFrozen = false;
					TheBillionaresParty.TargetVehicleA.PositionNoOffset = BillionairVehicleAReplay[Route_TargetVehA_Stage].Position;
					TheBillionaresParty.TargetVehicleA.Rotation = BillionairVehicleAReplay[Route_TargetVehA_Stage].Rotation;
					Memory.SetSteeringAngle(TheBillionaresParty.TargetVehicleA, BillionairVehicleAReplay[Route_TargetVehA_Stage].TurningAngle);
					Route_TargetVehA_Stage++;
				}
				else if (TheBillionaresParty.TargetVehicleADriver.IsAlive)
				{
					Vector3 position = TheBillionaresParty.TargetVehicleParked.Entities[0].Position;
					float z = TheBillionaresParty.TargetVehicleParked.Entities[0].Rotation.Z;
					if (GetDistance_VDIST2(TheBillionaresParty.TargetVehicleA.Position, position, "<", 10f) && !TheBillionaresParty.TargetVehicleA_NoLongerAvailable)
					{
						TheBillionaresParty.TargetVehicleA_NoLongerAvailable = true;
						if (TheBillionaresParty.TargetVehicleA.AttachedBlip != null)
						{
							TheBillionaresParty.TargetVehicleADriver.Opacity = 0;
							TheBillionaresParty.TargetVehicleA.AttachedBlip.Alpha = 0;
						}
						EntityFlickerEffect.VehicleFadeEffects.Add(new EntityFlickerEffect.FadeEffect(TheBillionaresParty.TargetVehicleA, true));
						Main.TextNotification("CHAR_LESTER", "Lester", "Target VehicleA Escaped", "Target Vehicle A has escaped, payment for Heist Completion has decreased!");
					}
					if (TargetVehA_DriveTimer != 30)
					{
						TargetVehA_DriveTimer++;
					}
					else
					{
						if (GetDistance_VDIST2(TheBillionaresParty.TargetVehicleA.Position, position, ">", 50f))
						{
							TheBillionaresParty.TargetVehicleADriver.Task.DriveTo(TheBillionaresParty.TargetVehicleA, position, 20f, 100f, DrivingStyle.AvoidTrafficExtremely);
						}
						else
						{
							Function.Call(Hash.TASK_VEHICLE_PARK, TheBillionaresParty.TargetVehicleADriver, TheBillionaresParty.TargetVehicleA, position.X, position.Y, position.Z, z, 1, 5f, false);
						}
						TargetVehA_DriveTimer = 0;
					}
				}
			}
			if (Playing_TargetVehB_Route && TheBillionaresParty.TargetVehicleB != null && TheBillionaresParty.TargetVehicleBDriver != null)
			{
				if (Route_TargetVehB_Stage < BillionairVehicleBReplay.Count - 1)
				{
					TheBillionaresParty.TargetVehicleB.IsPositionFrozen = false;
					TheBillionaresParty.TargetVehicleB.PositionNoOffset = BillionairVehicleBReplay[Route_TargetVehB_Stage].Position;
					TheBillionaresParty.TargetVehicleB.Rotation = BillionairVehicleBReplay[Route_TargetVehB_Stage].Rotation;
					Memory.SetSteeringAngle(TheBillionaresParty.TargetVehicleB, BillionairVehicleBReplay[Route_TargetVehB_Stage].TurningAngle);
					Route_TargetVehB_Stage++;
				}
				else if (TheBillionaresParty.TargetVehicleBDriver.IsAlive)
				{
					Vector3 position2 = TheBillionaresParty.TargetVehicleParked.Entities[1].Position;
					float z2 = TheBillionaresParty.TargetVehicleParked.Entities[1].Rotation.Z;
					if (GetDistance_VDIST2(TheBillionaresParty.TargetVehicleB.Position, position2, "<", 10f) && !TheBillionaresParty.TargetVehicleB_NoLongerAvailable)
					{
						TheBillionaresParty.TargetVehicleB_NoLongerAvailable = true;
						if (TheBillionaresParty.TargetVehicleB.AttachedBlip != null)
						{
							TheBillionaresParty.TargetVehicleBDriver.Opacity = 0;
							TheBillionaresParty.TargetVehicleB.AttachedBlip.Alpha = 0;
						}
						EntityFlickerEffect.VehicleFadeEffects.Add(new EntityFlickerEffect.FadeEffect(TheBillionaresParty.TargetVehicleB, true));
						Main.TextNotification("CHAR_LESTER", "Lester", "Target VehicleA Escaped", "Target Vehicle B has escaped, payment for Heist Completion has decreased!");
					}
					if (TargetVehB_DriveTimer != 30)
					{
						TargetVehB_DriveTimer++;
					}
					else
					{
						if (GetDistance_VDIST2(TheBillionaresParty.TargetVehicleB.Position, position2, ">", 50f))
						{
							TheBillionaresParty.TargetVehicleBDriver.Task.DriveTo(TheBillionaresParty.TargetVehicleB, position2, 20f, 100f, DrivingStyle.AvoidTrafficExtremely);
						}
						else
						{
							Function.Call(Hash.TASK_VEHICLE_PARK, TheBillionaresParty.TargetVehicleBDriver, TheBillionaresParty.TargetVehicleB, position2.X, position2.Y, position2.Z, z2, 1, 5f, false);
						}
						TargetVehB_DriveTimer = 0;
					}
				}
			}
			if (Playing_TargetVehC_Route && TheBillionaresParty.TargetVehicleC != null && TheBillionaresParty.TargetVehicleCDriver != null)
			{
				if (Route_TargetVehC_Stage < BillionairVehicleCReplay.Count - 1)
				{
					TheBillionaresParty.TargetVehicleC.IsPositionFrozen = false;
					TheBillionaresParty.TargetVehicleC.PositionNoOffset = BillionairVehicleCReplay[Route_TargetVehC_Stage].Position;
					TheBillionaresParty.TargetVehicleC.Rotation = BillionairVehicleCReplay[Route_TargetVehC_Stage].Rotation;
					Memory.SetSteeringAngle(TheBillionaresParty.TargetVehicleC, BillionairVehicleCReplay[Route_TargetVehC_Stage].TurningAngle);
					Route_TargetVehC_Stage++;
				}
				else if (TheBillionaresParty.TargetVehicleCDriver.IsAlive)
				{
					Vector3 position3 = TheBillionaresParty.TargetVehicleParked.Entities[2].Position;
					float z3 = TheBillionaresParty.TargetVehicleParked.Entities[2].Rotation.Z;
					if (GetDistance_VDIST2(TheBillionaresParty.TargetVehicleC.Position, position3, "<", 10f) && !TheBillionaresParty.TargetVehicleC_NoLongerAvailable)
					{
						TheBillionaresParty.TargetVehicleC_NoLongerAvailable = true;
						if (TheBillionaresParty.TargetVehicleC.AttachedBlip != null)
						{
							TheBillionaresParty.TargetVehicleCDriver.Opacity = 0;
							TheBillionaresParty.TargetVehicleC.AttachedBlip.Alpha = 0;
						}
						EntityFlickerEffect.VehicleFadeEffects.Add(new EntityFlickerEffect.FadeEffect(TheBillionaresParty.TargetVehicleC, true));
						Main.TextNotification("CHAR_LESTER", "Lester", "Target VehicleA Escaped", "Target Vehicle C has escaped, payment for Heist Completion has decreased!");
					}
					if (TargetVehC_DriveTimer != 30)
					{
						TargetVehC_DriveTimer++;
					}
					else
					{
						if (GetDistance_VDIST2(TheBillionaresParty.TargetVehicleC.Position, position3, ">", 50f))
						{
							TheBillionaresParty.TargetVehicleCDriver.Task.DriveTo(TheBillionaresParty.TargetVehicleC, position3, 20f, 100f, DrivingStyle.AvoidTrafficExtremely);
						}
						else
						{
							Function.Call(Hash.TASK_VEHICLE_PARK, TheBillionaresParty.TargetVehicleCDriver, TheBillionaresParty.TargetVehicleC, position3.X, position3.Y, position3.Z, z3, 1, 5f, false);
						}
						TargetVehC_DriveTimer = 0;
					}
				}
			}
			if (Playing_TargetVehD_Route && TheBillionaresParty.TargetVehicleD != null && TheBillionaresParty.TargetVehicleDDriver != null)
			{
				if (Route_TargetVehD_Stage < BillionairVehicleDReplay.Count - 1)
				{
					TheBillionaresParty.TargetVehicleD.IsPositionFrozen = false;
					TheBillionaresParty.TargetVehicleD.PositionNoOffset = BillionairVehicleDReplay[Route_TargetVehD_Stage].Position;
					TheBillionaresParty.TargetVehicleD.Rotation = BillionairVehicleDReplay[Route_TargetVehD_Stage].Rotation;
					Memory.SetSteeringAngle(TheBillionaresParty.TargetVehicleD, BillionairVehicleDReplay[Route_TargetVehD_Stage].TurningAngle);
					Route_TargetVehD_Stage++;
				}
				else if (TheBillionaresParty.TargetVehicleDDriver.IsAlive)
				{
					Vector3 position4 = TheBillionaresParty.TargetVehicleParked.Entities[3].Position;
					float z4 = TheBillionaresParty.TargetVehicleParked.Entities[3].Rotation.Z;
					if (GetDistance_VDIST2(TheBillionaresParty.TargetVehicleD.Position, position4, "<", 10f) && !TheBillionaresParty.TargetVehicleD_NoLongerAvailable)
					{
						TheBillionaresParty.TargetVehicleD_NoLongerAvailable = true;
						if (TheBillionaresParty.TargetVehicleD.AttachedBlip != null)
						{
							TheBillionaresParty.TargetVehicleDDriver.Opacity = 0;
							TheBillionaresParty.TargetVehicleD.AttachedBlip.Alpha = 0;
						}
						EntityFlickerEffect.VehicleFadeEffects.Add(new EntityFlickerEffect.FadeEffect(TheBillionaresParty.TargetVehicleD, true));
						Main.TextNotification("CHAR_LESTER", "Lester", "Target VehicleA Escaped", "Target Vehicle D has escaped, payment for Heist Completion has decreased!");
					}
					if (TargetVehD_DriveTimer != 30)
					{
						TargetVehD_DriveTimer++;
					}
					else
					{
						if (GetDistance_VDIST2(TheBillionaresParty.TargetVehicleD.Position, position4, ">", 50f))
						{
							TheBillionaresParty.TargetVehicleDDriver.Task.DriveTo(TheBillionaresParty.TargetVehicleD, position4, 20f, 100f, DrivingStyle.AvoidTrafficExtremely);
						}
						else
						{
							Function.Call(Hash.TASK_VEHICLE_PARK, TheBillionaresParty.TargetVehicleDDriver, TheBillionaresParty.TargetVehicleD, position4.X, position4.Y, position4.Z, z4, 1, 5f, false);
						}
						TargetVehD_DriveTimer = 0;
					}
				}
			}
			if (!PlayingRecordedRoute || !(RouteVeh != null))
			{
				return;
			}
			if (RouteStage < CurrentRoute.Count - 1)
			{
				RouteVeh.IsPositionFrozen = false;
				RouteVeh.PositionNoOffset = CurrentRoute[RouteStage].Position;
				RouteVeh.Rotation = CurrentRoute[RouteStage].Rotation;
				RouteStage++;
				drawText("ID " + RouteStage, 0.1f, 0.1f, 0.3f, 255, 255, 255);
				if (RouteVeh == YachtHeist.SuperVolito && RouteStage >= 150)
				{
					Function.Call(Hash.SET_HELI_BLADES_FULL_SPEED, RouteVeh);
				}
			}
			else if (RouteVeh == YachtHeist.SuperVolito)
			{
				RouteVeh.IsPositionFrozen = true;
			}
		}
	}
}
